	};
	const lazyRequestEffectClient: ExistingRequestEffectClient = {
		createWorkout: (...args) =>
			getRequestEffectClientOnce().createWorkout(...args),
		getBodyMeasurements: (...args) =>
			getRequestEffectClientOnce().getBodyMeasurements(...args),
