			events: createWorkoutsEventsOperation(lazyRequestEffectClient),
			get: createWorkoutsGetOperation(lazyRequestEffectClient),
			list: workoutsList,
			replaceExercises: createWorkoutsReplaceExercisesOperation(
				lazyRequestEffectClient,
