+
+/**
+ * Run a domain operation without introducing a Promise boundary.
+ *
+ * The execute fallback exists for older injected test doubles while the
+ * Effect-first operation API is being adopted. Production operations always
+ * return an Effect from `effect`, so this path is never selected there.
+ */
+export function operationEffect<
+	TArgs extends readonly unknown[],
+	TResult,
+>(
+	operation: EffectOperation<TArgs, TResult>,
+	...args: TArgs
+): Effect.Effect<TResult, unknown, never> {
+	return Effect.suspend(() => {
+		const result = operation.effect(...args);
+		if (Effect.isEffect(result)) {
+			return result;
+		}
+		if (operation.execute === undefined) {
+			return Effect.fail(
+				new Error("Effect operation returned a non-Effect result."),
+			);
+		}
+		return Effect.tryPromise(() => operation.execute(...args));
+	});
+}
