				items: response.items,
				pageCount: response.pageCount,
				endOfList: response.expected404Outcome === "end_of_list",
			})),
			Effect.catchIf(
				(error) =>
					isExpectedReadEndOfList(error, "/v1/body_measurements", page),
				() => Effect.succeed({ items: [], endOfList: true }),
			),
		);
	};
}

